<div class="titlebar"><div><h2>Kegiatan dan realisasi</h2><span class="muted">Realisasi sampai akhir bulan <?= $esc($month) ?> / <?= $esc($year) ?></span></div><div class="actions"><?php if($actor['role']!=='viewer'): ?><a class="button" href="<?= $url('form') ?>">+ Tambah kegiatan</a><?php endif; ?><a class="button secondary" href="<?= $url('export').'?'.http_build_query(['tahun'=>$year,'bulan'=>$month,'opd'=>$opd,'filter'=>$filter]) ?>">Unduh CSV</a><button class="secondary" onclick="window.print()">Cetak</button></div></div>
<form class="panel filters" method="get"><label>Tahun<input type="number" min="2000" max="2100" name="tahun" value="<?= $year ?>"></label><label>Bulan<select name="bulan"><?php for($i=1;$i<=12;$i++): ?><option value="<?= $i ?>" <?= $i===$month?'selected':'' ?>><?= $i ?></option><?php endfor; ?></select></label><label>OPD<select name="opd"><option value="0">Seluruh OPD</option><?php foreach($opds as $o): ?><option value="<?= $o['id_opd_pemkab'] ?>" <?= $opd==$o['id_opd_pemkab']?'selected':'' ?>><?= $esc($o['nama_opd']) ?></option><?php endforeach; ?></select></label><label>Klasifikasi<select name="filter"><?php foreach([''=>'Semua kegiatan','bkp'=>'BKP','infrastruktur'=>'Infrastruktur','psd'=>'PSD','phtc'=>'PHTC','tkd'=>'Tambahan TKD'] as $v=>$n): ?><option value="<?= $v ?>" <?= $filter===$v?'selected':'' ?>><?= $n ?></option><?php endforeach; ?></select></label><button>Tampilkan</button></form>
<div class="cards"><div class="card"><small>Jumlah kegiatan</small><strong><?= $rekap['jumlah_kegiatan'] ?></strong></div><div class="card"><small>Total pagu</small><strong class="money">Rp <?= $rupiah($rekap['total_pagu']) ?></strong></div><div class="card"><small>Progres fisik berbobot pagu</small><strong><?= $rekap['persen_fisik'] ?>%</strong></div><div class="card"><small>Realisasi keuangan berbobot</small><strong><?= $rekap['persen_keuangan'] ?>%</strong></div></div>
<div class="panel"><h2>Rekap per OPD</h2><div class="table-wrap"><table><thead><tr><th>OPD</th><th>Jumlah</th><th>Pagu</th><th>Nilai kontrak</th><th>Keuangan</th><th>Fisik</th></tr></thead><tbody><?php $groups=[];foreach($rows as $r)$groups[$r['id_opd_pemkab']][]=$r;foreach($groups as $oid=>$group):$g=Pemkab_rules::rekap($group); ?><tr><td><a href="<?= $url().'?'.http_build_query(['tahun'=>$year,'bulan'=>$month,'opd'=>$oid,'filter'=>$filter]) ?>"><?= $esc($group[0]['nama_opd']) ?></a></td><td><?= $g['jumlah_kegiatan'] ?></td><td class="num"><?= $rupiah($g['total_pagu']) ?></td><td class="num"><?= $rupiah($g['total_nilai']) ?></td><td class="num"><?= $g['persen_keuangan'] ?>%</td><td class="num"><?= $g['persen_fisik'] ?>%</td></tr><?php endforeach; ?></tbody></table></div></div>
<div class="panel"><h2>Daftar kegiatan</h2><div class="table-wrap"><table><thead><tr><th>Kegiatan / OPD</th><th>Pagu / Kontrak (Rp)</th><th>Keuangan (Rp)</th><th>Fisik</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><a class="name" href="<?= $url('detail/'.$r['id_kegiatan']) ?>"><?= $esc($r['keperluan']) ?></a><small><?= $esc($r['nama_opd']) ?></small><br><?php foreach(['status_1'=>'BKP','status_3'=>'Infrastruktur','tkd'=>'TKD'] as $f=>$n)if($r[$f]==='Y')echo '<span class="badge">'.$n.'</span> '; ?></td><td class="num"><?= $rupiah($r['pagu']) ?><br><small><?= $rupiah($r['nilai']) ?></small></td><td class="num"><?= $rupiah($r['realisasi_periode']) ?><br><small><?= (float)$r['nilai']>0?round((float)$r['realisasi_periode']/(float)$r['nilai']*100,2):0 ?>%</small></td><td class="num"><?= $esc($r['fisik_periode']) ?>%</td><td><?= ['B'=>'Belum','P'=>'Proses','S'=>'Selesai'][$r['st_kontrak']] ?></td><td><a href="<?= $url('detail/'.$r['id_kegiatan']) ?>">Detail</a><?php if($actor['role']!=='viewer'): ?><br><a href="<?= $url('form/'.$r['id_kegiatan']) ?>">Ubah</a><?php endif; ?></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="6">Belum ada kegiatan pada filter ini. Aktifkan OPD per tahun sebelum menambah kegiatan.</td></tr><?php endif; ?></tbody></table></div></div>
